<?php
namespace App\Http\Controllers;
use App\Models\{Familia,EtapaProduccion,ControlCalidad,FamiliaControlCalidad,UnidadProduccion};
use App\Services\CalidadDocumental as C;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Storage};
class PlanillaCalidadController extends Controller {
 private function doc($f){return DB::table('calidad_documentos')->where('familia_id',$f->id)->first();}
 private function rev($f,$id){$r=C::revision($id);abort_unless($r && $r->documento_id===$this->doc($f)?->id,404);return $r;}
 private function editable($r,Request $q): void {abort_unless($r->estado==='borrador',422,'La revisión publicada no se edita. Creá una nueva revisión.');if(!hash_equals(hash('sha256',json_encode([$r->contenido,$r->revision,$r->motivo,$r->updated_at])),$q->input('version','')))throw \Illuminate\Validation\ValidationException::withMessages(['version'=>'Este formulario corresponde a una versión anterior del borrador. Se cargó la versión actual; revisá el ítem y volvé a guardar. No se aplicó el envío anterior para evitar sobrescribir cambios.']);}
 public function index(Familia $familia){$documento=$this->doc($familia);$revisiones=$documento ? DB::table('calidad_revisiones')->where('documento_id',$documento->id)->orderByDesc('numero')->get() : collect();return view('calidad.documentos.index',compact('familia','documento','revisiones'));}
 public function crear(Request $q,Familia $familia){$d=$q->validate(['codigo'=>['required','string','max:100'],'nombre'=>['required','string','max:255']]);DB::transaction(function()use($familia,$d){abort_if($this->doc($familia),422,'La familia ya tiene una planilla.');$id=DB::table('calidad_documentos')->insertGetId($d+['familia_id'=>$familia->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('calidad_revisiones')->insert(['documento_id'=>$id,'numero'=>1,'estado'=>'borrador','contenido'=>json_encode(['items'=>[],'imagenes'=>[]]),'preparado_por'=>auth()->user()->name,'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Planilla creada en borrador.');}
 public function nueva(Request $q,Familia $familia){DB::transaction(function()use($familia){$doc=DB::table('calidad_documentos')->where('familia_id',$familia->id)->lockForUpdate()->first();abort_unless($doc,404);abort_if(DB::table('calidad_revisiones')->where('documento_id',$doc->id)->where('estado','borrador')->exists(),422,'Ya hay un borrador abierto.');$ultima=DB::table('calidad_revisiones')->where('documento_id',$doc->id)->orderByDesc('numero')->first();DB::table('calidad_revisiones')->insert(['documento_id'=>$doc->id,'numero'=>$ultima->numero+1,'estado'=>'borrador','contenido'=>$ultima->contenido,'preparado_por'=>auth()->user()->name,'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Nueva revisión en borrador. La anterior se conserva.');}
 public function edit(Familia $familia,int $revision){$r=$this->rev($familia,$revision);$contenido=json_decode($r->contenido,true);$etapas=EtapaProduccion::where('alcance','unidad')->where('activo',true)->orderBy('orden')->get();$version=hash('sha256',json_encode([$r->contenido,$r->revision,$r->motivo,$r->updated_at]));return view('calidad.documentos.editar',compact('familia','r','contenido','etapas','version'));}
 public function guardar(Request $q,Familia $familia,int $revision){DB::transaction(function()use($q,$familia,$revision){DB::table('calidad_revisiones')->where('id',$revision)->lockForUpdate()->first();$r=$this->rev($familia,$revision);$this->editable($r,$q);$c=json_decode($r->contenido,true);
  if($q->input('accion')==='seccion'){
   $d=$q->validate(['nombre_seccion'=>['required','string','max:255'],'seccion_anterior'=>['nullable','string','max:255']]);
   $nombre=trim($d['nombre_seccion']);if($nombre==='')throw \Illuminate\Validation\ValidationException::withMessages(['nombre_seccion'=>'Ingresá el nombre de la sección.']);
   $anterior=$d['seccion_anterior']??null;
   $secciones=collect($c['secciones']??[])->merge(collect($c['items'])->pluck('seccion'))->merge(collect($c['imagenes'])->pluck('seccion'))->filter()->unique()->values()->all();
   if($anterior && $anterior!==$nombre && in_array($nombre,$secciones,true))throw \Illuminate\Validation\ValidationException::withMessages(['nombre_seccion'=>'Ya existe una sección con ese nombre.']);
   if($anterior){foreach($c['items'] as &$punto){if($punto['seccion']===$anterior)$punto['seccion']=$nombre;}unset($punto);foreach($c['imagenes'] as &$imagen){if($imagen['seccion']===$anterior)$imagen['seccion']=$nombre;}unset($imagen);$secciones=array_map(fn($s)=>$s===$anterior?$nombre:$s,$secciones);}
   $c['secciones']=array_values(array_unique([...$secciones,$nombre]));
   DB::table('calidad_revisiones')->where('id',$r->id)->update(['contenido'=>json_encode($c),'updated_at'=>now()]);return;
  }
  if($q->input('accion')==='cabecera'){$d=$q->validate(['revision'=>['required','string','max:80'],'motivo'=>['required','string','max:5000']]);DB::table('calidad_revisiones')->where('id',$r->id)->update($d+['updated_at'=>now()]);return;}
  if($q->input('accion')==='imagen'){$q->validate(['imagen'=>['required','image','mimes:jpg,jpeg,png,webp','max:5120'],'seccion'=>['required','string','max:255'],'pie'=>['required','string','max:500']]);$path=$q->file('imagen')->store('calidad/referencias','local');$c['imagenes'][]=['path'=>$path,'seccion'=>$q->seccion,'pie'=>$q->pie];}
  elseif($q->input('accion')==='quitar_imagen'){abort_unless(isset($c['imagenes'][$q->integer('indice')]),404);array_splice($c['imagenes'],$q->integer('indice'),1);}
  elseif($q->input('accion')==='quitar'){abort_unless(isset($c['items'][$q->integer('indice')]),404);array_splice($c['items'],$q->integer('indice'),1);}
  else{$d=$q->validate(['nombre'=>['required','string','max:1000'],'seccion'=>['required','string','max:255'],'etapa_id'=>['required',\Illuminate\Validation\Rule::exists(EtapaProduccion::class,'id')->where('alcance','unidad')],'tipo_respuesta'=>['required','in:si_no,valor,texto'],'descripcion'=>['nullable','string','max:5000'],'condicion'=>['nullable','string','max:500'],'unidad_medida'=>['nullable','string','max:50'],'min'=>['nullable','numeric'],'max'=>['nullable','numeric','gte:min'],'obligatorio'=>['nullable','boolean']]);$d['obligatorio']=$q->boolean('obligatorio');$d['orden']=$q->integer('indice',count($c['items']))+1;
   if($q->has('indice')){abort_unless(isset($c['items'][$q->integer('indice')]),404);$previo=$c['items'][$q->integer('indice')];if(isset($previo['control_id']))$d['control_id']=$previo['control_id'];if(!empty($previo['espesor']))$d['espesor']=true;$c['items'][$q->integer('indice')]=$d;}else $c['items'][]=$d;
  }
  DB::table('calidad_revisiones')->where('id',$r->id)->update(['contenido'=>json_encode($c),'updated_at'=>now()]);
 });return back()->with('success','Borrador guardado.');}
 public function publicar(Request $q,Familia $familia,int $revision){$d=$q->validate(['confirmar'=>['accepted'],'vigente_desde'=>['required','date','before_or_equal:today']]);DB::transaction(function()use($q,$familia,$revision,$d){$doc=DB::table('calidad_documentos')->where('familia_id',$familia->id)->lockForUpdate()->first();$r=$this->rev($familia,$revision);$this->editable($r,$q);$c=json_decode($r->contenido,true);$c['items']=\App\Services\ConfiguracionCalidad::ordenar($c['items']);$faltantes=[];
   if(trim((string)$r->revision)==='')$faltantes['revision']='Completá la revisión documental y presioná «Guardar cabecera» antes de aprobar.';
   if(trim((string)$r->motivo)==='')$faltantes['motivo']='Completá el motivo del cambio y presioná «Guardar cabecera» antes de aprobar.';
   if(!collect($c['items'])->contains(fn($i)=>($i['activo']??true) && ($i['seccion_activa']??true)))$faltantes['items']='Agregá al menos un ítem de control antes de aprobar.';
   if($faltantes)throw \Illuminate\Validation\ValidationException::withMessages($faltantes);
   // Cada publicación crea controles nuevos, sin reescribir definiciones usadas anteriormente.
   FamiliaControlCalidad::where('familia_id',$familia->id)->update(['activo'=>false]);
   foreach($c['items'] as $i=>&$item){$orden=$item['orden']??($i+1);$e=EtapaProduccion::whereKey($item['etapa_id'])->where('activo',true)->where('alcance','unidad')->firstOrFail();$control=ControlCalidad::create(['nombre'=>\Illuminate\Support\Str::limit($item['nombre'],250,''),'descripcion'=>$item['descripcion']??null,'tipo_respuesta'=>$item['tipo_respuesta'],'orden'=>$orden,'obligatorio'=>$item['obligatorio'],'activo'=>($item['activo']??true) && ($item['seccion_activa']??true),'calidad_seccion_id'=>$item['seccion_id']??null]);$item['control_id']=$control->id;$item['orden']=$orden;
    FamiliaControlCalidad::create(['familia_id'=>$familia->id,'control_calidad_id'=>$control->id,'etapa_produccion_id'=>$e->id,'orden'=>$orden,'obligatorio'=>$item['obligatorio'],'activo'=>($item['activo']??true) && ($item['seccion_activa']??true),'unidad_medida'=>$item['unidad_medida']??null,'valor_minimo'=>$item['min']??null,'valor_maximo'=>$item['max']??null]);}
   DB::table('calidad_revisiones')->where('documento_id',$doc->id)->where('estado','vigente')->update(['estado'=>'obsoleta','updated_at'=>now()]);
   DB::table('calidad_revisiones')->where('id',$r->id)->update(['estado'=>'vigente','contenido'=>json_encode($c),'aprobado_por'=>auth()->user()->name,'aprobado_at'=>now(),'vigente_desde'=>$d['vigente_desde'],'updated_at'=>now()]);
  });return redirect()->route('calidad.documentos.index',$familia)->with('success','Revisión aprobada. Los chasis con controles previos conservan su registro.');}
 public function imprimir(Familia $familia,int $revision){$r=$this->rev($familia,$revision);$contenido=json_decode($r->contenido,true);$unidad=null;$controles=collect();return view('calidad.documentos.imprimir',compact('familia','r','contenido','unidad','controles'));}
 public function registro(UnidadProduccion $unidad){C::preparar($unidad);$familia=$unidad->planProducto->producto->familia;$r=C::revision($unidad->calidad_revision_id);$controles=$unidad->controlesCalidad()->with('control','etapa')->get();$contenido=$r ? json_decode($r->contenido,true) : ['imagenes'=>[],'items'=>[]];return view('calidad.documentos.imprimir',compact('familia','r','contenido','unidad','controles'));}
 public function adoptar(Request $q,UnidadProduccion $unidad){$q->validate(['confirmar'=>['accepted']]);DB::transaction(function()use($unidad){$u=UnidadProduccion::whereKey($unidad->id)->lockForUpdate()->firstOrFail();abort_if(in_array($u->estado,['entregada','cancelada']),422,'La unidad está cerrada.');$rev=C::vigente($u->planProducto->producto->familia_id);abort_unless($rev,422,'No hay revisión vigente.');$rows=$u->controlesCalidad()->lockForUpdate()->get();abort_if($rows->contains(fn($r)=>$r->resultado!=='pendiente'||$r->valor||$r->observaciones||$r->evidencia_path||$r->fecha_control),422,'Ya hay controles registrados. Conservá la revisión asignada.');C::historial($u->id,null,['revision'=>$u->calidad_revision_id,'controles'=>$rows->toArray()],['revision'=>$rev->id],'Aplicación explícita de revisión vigente a controles sin iniciar');$u->controlesCalidad()->delete();$u->forceFill(['calidad_revision_id'=>null,'calidad_fijada_at'=>null])->save();C::preparar($u);});return back()->with('success','Revisión vigente asignada a esta unidad.');}
 public function editarItem(Request $q,Familia $familia,int $control){$e=\App\Services\ConfiguracionCalidad::estado($familia);foreach($e['c']['items'] as $i=>$item)if(($item['control_id']??null)==$control)return redirect()->route('calidad.configuracion.editar',[$familia,$i]);return redirect()->route('calidad.familias.controles.index',$familia)->with('error','Ese control pertenece a una revisión anterior. Abrí el control actual desde el listado.');}
 public function imagen(int $revision,int $indice){$r=C::revision($revision);abort_unless($r,404);$c=json_decode($r->contenido,true);$img=$c['imagenes'][$indice]??null;abort_unless($img && Storage::disk('local')->exists($img['path']),404);return response()->file(Storage::disk('local')->path($img['path']));}
}
